  rep('fin', 'tax', 'تقرير الضريبة', 'Tax report', 'ضريبة مخرجات الفواتير ومدخلات المصروفات.', 'Output VAT on invoices and input VAT on expenses.', P => { const ms = M.monthsBetween(P.from.slice(0, 7), P.to.slice(0, 7)); const db = U.db(); const rows = ms.map(ym => { const out = M.sum(db.invoices.filter(i => M.month(i.issueDate) === ym), i => i.tax) - M.sum(db.creditNotes.filter(c => M.month(c.date) === ym), c => c.tax); const inn = M.sum(db.expenses.filter(e => M.month(e.date) === ym), e => e.tax) + M.sum(db.movements.filter(m => m.type === 'receipt' && M.month(m.date) === ym), m => m.value * 0.14); return { ym, out, inn, net: out - inn }; }); return { rows, columns: [{ label: tt('الشهر', 'Month'), value: r => r.ym, render: r => M.monthName(r.ym) }, col(tt('ضريبة مخرجات', 'Output VAT'), 'out', { money: 1 }), col(tt('ضريبة مدخلات', 'Input VAT'), 'inn', { money: 1 }), col(tt('صافي المستحق', 'Net payable'), 'net', { money: 1 })], footer: sumFoot(['out', 'inn', 'net']) }; });
