  rep('fin', 'payback', 'استرداد رأس المال', 'Capital recovery & payback', 'نسبة الاسترداد والتاريخ المتوقع لكل مركبة.', 'Recovery % and expected payback per vehicle.', P => ({ rows: U.db().vehicles.map(v => Object.assign({ v, price: v.purchasePrice }, C.capital(U.cid(), v))), columns: [vcol(), col(tt('سعر الشراء', 'Purchase price'), 'price', { money: 1 }), col(tt('المسترد', 'Recovered'), 'recovered', { money: 1 }), { label: tt('النسبة', 'Recovered %'), num: 1, value: r => r.pct, render: r => M.pct(Math.min(r.pct, 9.99), 0) }, col(tt('متوسط شهري', 'Monthly avg'), 'monthly', { money: 1 }), { label: tt('تاريخ الاسترداد', 'Payback date'), value: r => r.paybackDate || 'z', render: r => r.remaining <= 0 ? U.badge(tt('تم', 'Done'), 'success') : r.paybackDate ? M.date(r.paybackDate) : U.badge(tt('لا يسترد', 'Not recovering'), 'danger') }], note: tt(`الفترة قبل ${M.date(M.START)} تقديرية.`, `Months before ${M.date(M.START)} are estimated.`) }));
