  rep('ana', 'roc', 'العائد على رأس المال', 'Return on capital', 'أنهي فئة تستحق الاستثمار أكتر.', 'Which category is most worth investing in.', P => { const rows = C.typePL(U.cid(), P.from, P.to); return { rows, chart: bar(rows.map(r => U.vtype(r.type)), rows.map(r => +((r.roc || 0) * 100).toFixed(1)), tt('عائد سنوي %', 'Annualized %'), rows.map(r => r.roc < 0 ? '#B91C1C' : '#08264A')), columns: [{ label: tt('النوع', 'Type'), value: r => r.type, render: r => U.vtype(r.type) }, col(tt('عدد', 'Count'), 'count', { num: 1 }), col(tt('القيمة الدفترية', 'Book value'), 'book', { money: 1 }), col(tt('صافي الربح', 'Net profit'), 'net', { money: 1 }), { label: tt('العائد السنوي', 'Annualized return'), num: 1, value: r => r.roc, render: r => `<b class="${r.roc < 0 ? 'neg' : ''}">${M.pct(r.roc)}</b>` }, col(tt('نسبة التشغيل', 'Utilization'), 'util', { pct: 1 })] }; });
  rep('ana', 'keep', 'نستبدل ولا نكمّل', 'Keep vs replace', 'اتجاه الصيانة مقابل القيمة الدفترية والعمر المتبقي.', 'Maintenance trend vs book value and remaining life.', P => { const cid = U.cid(); const rows = U.db().vehicles.map(v => { const d = C.dep(v); const m6 = M.sum(U.db().workOrders.filter(w => w.vehicleId === v.id && w.date >= M.addDays(M.TODAY, -183)), w => w.total); const ratio = m6 / d.book; return { v, book: d.book, m6, ratio, life: d.pctLife, verdict: ratio > 0.2 || d.pctLife > 0.9 ? 'replace' : ratio > 0.1 || d.pctLife > 0.75 ? 'watch' : 'keep' }; }).sort((a, b) => b.ratio - a.ratio); return { rows, columns: [vcol(), col(tt('القيمة الدفترية', 'Book value'), 'book', { money: 1 }), col(tt('صيانة 6 شهور', 'Maintenance 6m'), 'm6', { money: 1 }), col(tt('صيانة ÷ قيمة', 'Maint ÷ value'), 'ratio', { pct: 1 }), col(tt('العمر المستهلك', 'Life used'), 'life', { pct: 1 }), { label: tt('التوصية', 'Signal'), value: r => r.verdict, render: r => r.verdict === 'replace' ? U.badge(tt('فكّر في الاستبدال', 'Consider replacing'), 'danger') : r.verdict === 'watch' ? U.badge(tt('تحت المراقبة', 'Watch'), 'warning') : U.badge(tt('كمّل', 'Keep'), 'success') }] }; });
  rep('ana', 'breakeven', 'نقطة التعادل لكل مركبة', 'Break-even per vehicle', 'الإيراد الشهري المطلوب لتغطية التكاليف الثابتة والمتغيرة.', 'Monthly revenue needed to cover fixed and variable costs.', P => { const rows = C.fleetPL(U.cid(), P.from, P.to).rows.map(r => { const months = r.days / 30.44; const fixed = (r.driver + r.licIns + r.depreciation) / months; const varRatio = r.revenue ? (r.fuel + r.oil + r.maintenance + r.tripExp) / r.revenue : 0.3; const be = fixed / Math.max(0.05, 1 - varRatio); return { v: r.v, fixed, varRatio, be, actual: r.revenue / months }; }); return { rows, columns: [vcol(), col(tt('تكاليف ثابتة/شهر', 'Fixed/month'), 'fixed', { money: 1 }), col(tt('نسبة المتغيرة', 'Variable ratio'), 'varRatio', { pct: 1 }), col(tt('إيراد التعادل/شهر', 'Break-even revenue/month'), 'be', { money: 1 }), { label: tt('الإيراد الفعلي/شهر', 'Actual revenue/month'), num: 1, value: r => r.actual, render: r => `<span class="${r.actual < r.be ? 'neg' : 'pos'}">${M.money(r.actual)}</span>` }] }; });
